def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find a uniform row or column separating two equal-sized panels.
    for c in range(w):
        if all(grid[r][c] == grid[0][c] for r in range(h)):
            left, right = c, w - c - 1
            if left == right and left > 0:
                panels = (
                    [row[:c] for row in grid],
                    [row[c + 1:] for row in grid],
                )
                common = set(sum(panels[0], [])) & set(sum(panels[1], []))
                color = min(common)
                return [
                    [3 if a == color and b == color else color
                     for a, b in zip(row_a, row_b)]
                    for row_a, row_b in zip(*panels)
                ]

    for r in range(h):
        if all(x == grid[r][0] for x in grid[r]):
            top, bottom = r, h - r - 1
            if top == bottom and top > 0:
                panels = (grid[:r], grid[r + 1:])
                common = set(sum(panels[0], [])) & set(sum(panels[1], []))
                color = min(common)
                return [
                    [3 if a == color and b == color else color
                     for a, b in zip(row_a, row_b)]
                    for row_a, row_b in zip(panels[0], panels[1])
                ]

    return grid
